app_css:
.tool-app-pushproof { color: #0c4a6e; max-width: 860px; }
.tool-app-pushproof .pp-stats { display: flex; gap: 10px; flex-wrap: wrap; margin: 12px 0; }
.tool-app-pushproof .pp-stat { flex: 1 1 140px; background: #f0f9ff; border: 1px solid #bae6fd; border-radius: 10px; padding: 10px 14px; }
.tool-app-pushproof .pp-stat span { display: block; font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; color: #0369a1; font-weight: 700; }
.tool-app-pushproof .pp-stat strong { font-size: 20px; color: #0c4a6e; }
.tool-app-pushproof .pp-tabs { display: flex; gap: 6px; flex-wrap: wrap; margin: 10px 0 14px; }
.tool-app-pushproof .pp-tab { border: 1px solid #bae6fd; background: #fff; color: #0369a1; border-radius: 999px; padding: 8px 14px; font-size: 13px; font-weight: 700; cursor: pointer; }
.tool-app-pushproof .pp-tab.pp-active { background: #0284C7; border-color: #0284C7; color: #fff; }
.tool-app-pushproof .pp-card { background: #f0f9ff; border: 1px solid #bae6fd; border-radius: 12px; padding: 14px; margin-bottom: 12px; }
.tool-app-pushproof .pp-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.tool-app-pushproof .pp-form-grid .pp-btn { grid-column: 1 / -1; justify-self: start; }
.tool-app-pushproof label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; color: #075985; }
.tool-app-pushproof input[type="text"], .tool-app-pushproof input[type="number"], .tool-app-pushproof input[type="file"], .tool-app-pushproof select { border: 1px solid #7dd3fc; border-radius: 8px; padding: 9px 10px; font-size: 14px; width: 100%; box-sizing: border-box; background: #fff; color: #0c4a6e; }
.tool-app-pushproof .pp-pane .pp-card label { margin-bottom: 10px; }
.tool-app-pushproof .pp-btn { background: #0284C7; color: #fff; border: none; border-radius: 10px; padding: 12px 20px; font-size: 15px; font-weight: 700; cursor: pointer; }
.tool-app-pushproof .pp-btn:hover { background: #0369a1; }
.tool-app-pushproof .pp-btn:disabled { background: #7dd3fc; cursor: wait; }
.tool-app-pushproof .pp-btn-ghost { background: #e0f2fe; color: #0369a1; }
.tool-app-pushproof .pp-btn-ghost:hover { background: #bae6fd; }
.tool-app-pushproof .pp-hint { font-size: 13px; color: #0369a1; margin: 10px 0 0; }
.tool-app-pushproof .pp-ok { background: #dcfce7; border: 1px solid #86efac; color: #166534; border-radius: 10px; padding: 10px 14px; font-size: 14px; margin: 10px 0 0; }
.tool-app-pushproof .pp-row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 12px; }
.tool-app-pushproof .pp-list { list-style: none; padding: 0; margin: 0; }
.tool-app-pushproof .pp-list li { background: #f0f9ff; border: 1px solid #bae6fd; border-radius: 10px; padding: 10px 12px; margin-bottom: 8px; font-size: 14px; }
.tool-app-pushproof .pp-list .pp-li-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.tool-app-pushproof .pp-list .pp-li-title { font-weight: 700; }
.tool-app-pushproof .pp-list .pp-li-meta { font-size: 12px; color: #0369a1; margin-top: 4px; }
.tool-app-pushproof .pp-list .pp-li-meta a { color: #0284C7; }
.tool-app-pushproof .pp-thumb { max-width: 120px; border-radius: 8px; margin-top: 6px; display: block; }
.tool-app-pushproof .pp-badge { font-size: 11px; font-weight: 700; border-radius: 999px; padding: 3px 10px; white-space: nowrap; }
.tool-app-pushproof .pp-badge.pp-open { background: #fef9c3; color: #854d0e; }
.tool-app-pushproof .pp-badge.pp-closed { background: #e2e8f0; color: #475569; }
.tool-app-pushproof .pp-badge.pp-unbilled { background: #ffedd5; color: #9a3412; }
.tool-app-pushproof .pp-badge.pp-billed { background: #dcfce7; color: #166534; }
.tool-app-pushproof .pp-del { background: none; border: none; color: #b91c1c; cursor: pointer; font-size: 18px; line-height: 1; }
.tool-app-pushproof .pp-actions { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 10px; }
.tool-app-pushproof .pp-billtotals { display: flex; gap: 10px; flex-wrap: wrap; margin: 12px 0; }
.tool-app-pushproof .pp-billtotals div { background: #e0f2fe; border-radius: 8px; padding: 8px 12px; font-size: 13px; }
.tool-app-pushproof .pp-billtotals strong { display: block; font-size: 18px; }
.tool-app-pushproof .pp-small { font-size: 12px; color: #0369a1; margin-top: 6px; }

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  function fmtTs(ts) {
    var d = new Date(ts);
    return d.toLocaleDateString() + ' ' + d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  }
  function uid() { return 'x' + Date.now().toString(36) + Math.floor(Math.random() * 1e6).toString(36); }

  var K_PROPS = 'toolapp-pushproof-props';
  var K_EVENTS = 'toolapp-pushproof-events';
  var K_RECS = 'toolapp-pushproof-records';

  function load(k) { try { return JSON.parse(localStorage.getItem(k)) || []; } catch (e) { return []; } }
  function save(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }

  var root = $('toolAppRoot');

  function propName(id) {
    var p = load(K_PROPS);
    for (var i = 0; i < p.length; i++) if (p[i].id === id) return p[i].name;
    return 'Unknown property';
  }
  function propRate(id) {
    var p = load(K_PROPS);
    for (var i = 0; i < p.length; i++) if (p[i].id === id) return parseFloat(p[i].rate) || 0;
    return 0;
  }
  function eventName(id) {
    var ev = load(K_EVENTS);
    for (var i = 0; i < ev.length; i++) if (ev[i].id === id) return ev[i].name;
    return 'Unknown storm';
  }
  function activeEvent() {
    var ev = load(K_EVENTS);
    for (var i = 0; i < ev.length; i++) if (ev[i].status === 'open') return ev[i];
    return ev.length ? ev[0] : null;
  }
  function ensureEvent() {
    var a = activeEvent();
    if (a) return a;
    var d = new Date();
    a = { id: uid(), name: 'Storm ' + d.toLocaleDateString(), status: 'open', created: Date.now() };
    var ev = load(K_EVENTS);
    ev.unshift(a);
    save(K_EVENTS, ev);
    return a;
  }

  function getGPS(cb) {
    if (!navigator.geolocation) { cb(null, 'GPS not supported on this device.'); return; }
    var done = false;
    function fin(pos, err) { if (done) return; done = true; cb(pos, err); }
    navigator.geolocation.getCurrentPosition(
      function (p) { fin({ lat: p.coords.latitude, lng: p.coords.longitude, acc: Math.round(p.coords.accuracy || 0) }, null); },
      function (e) { fin(null, e && e.message ? e.message : 'Location unavailable'); },
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 60000 }
    );
  }

  function readPhoto(file, cb) {
    if (!file) { cb(null); return; }
    var reader = new FileReader();
    reader.onload = function () {
      var img = new Image();
      img.onload = function () {
        var max = 800, w = img.width, h = img.height;
        var scale = Math.min(1, max / Math.max(w, h));
        var c = document.createElement('canvas');
        c.width = Math.max(1, Math.round(w * scale));
        c.height = Math.max(1, Math.round(h * scale));
        c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
        try { cb(c.toDataURL('image/jpeg', 0.7)); } catch (e) { cb(null); }
      };
      img.onerror = function () { cb(null); };
      img.src = reader.result;
    };
    reader.onerror = function () { cb(null); };
    reader.readAsDataURL(file);
  }

  function refreshStats() {
    var recs = load(K_RECS);
    var a = activeEvent();
    var evRecs = a ? recs.filter(function (r) { return r.eventId === a.id; }) : [];
    var unbilled = 0;
    recs.forEach(function (r) { if (!r.billed) unbilled += propRate(r.propId); });
    $('pp-stats').innerHTML =
      '<div class="pp-stat"><span>Active storm</span><strong>' + esc(a ? a.name : '—') + '</strong></div>' +
      '<div class="pp-stat"><span>Pushes this storm</span><strong>' + evRecs.length + '</strong></div>' +
      '<div class="pp-stat"><span>Unbilled total</span><strong>' + money(unbilled) + '</strong></div>';
  }

  function fillEventSelect(sel, includeAll) {
    var ev = load(K_EVENTS);
    var html = includeAll ? '<option value="">All storms</option>' : '';
    ev.forEach(function (e) {
      html += '<option value="' + e.id + '"' + (e.status === 'open' ? ' selected' : '') + '>' +
        esc(e.name) + (e.status === 'closed' ? ' (closed)' : '') + '</option>';
    });
    sel.innerHTML = html;
    if (!includeAll && !ev.length) sel.innerHTML = '<option value="">—</option>';
  }
  function fillPropSelect(sel, includeAll) {
    var p = load(K_PROPS);
    var html = includeAll ? '<option value="">All properties</option>' : '';
    p.forEach(function (x) { html += '<option value="' + x.id + '">' + esc(x.name) + '</option>'; });
    sel.innerHTML = html;
    if (!includeAll && !p.length) sel.innerHTML = '<option value="">—</option>';
  }
  function syncLogSelectors() {
    var a = ensureEvent();
    fillEventSelect($('pp-event'), false);
    $('pp-event').value = a.id;
    fillPropSelect($('pp-prop'), false);
  }

  function renderRecords() {
    fillEventSelect($('pp-rec-event'), true);
    fillPropSelect($('pp-rec-prop'), true);
    var evF = $('pp-rec-event').getAttribute('data-sel') || '';
    var pF = $('pp-rec-prop').getAttribute('data-sel') || '';
    $('pp-rec-event').value = evF;
    $('pp-rec-prop').value = pF;
    var recs = load(K_RECS).filter(function (r) {
      return (!evF || r.eventId === evF) && (!pF || r.propId === pF);
    });
    recs.sort(function (x, y) { return y.ts - x.ts; });
    var ul = $('pp-records');
    ul.innerHTML = '';
    if (!recs.length) {
      var li0 = document.createElement('li');
      li0.textContent = 'No pushes logged yet. Go to Log push and stamp the first one.';
      ul.appendChild(li0);
      return;
    }
    recs.forEach(function (r) {
      var li = document.createElement('li');
      var gps = r.lat != null
        ? '<a href="https://maps.google.com/?q=' + r.lat.toFixed(6) + ',' + r.lng.toFixed(6) + '" target="_blank" rel="noopener">GPS ' +
          r.lat.toFixed(5) + ', ' + r.lng.toFixed(5) + (r.acc ? ' (±' + r.acc + 'm)' : '') + '</a>'
        : 'No GPS captured';
      var photo = r.photo ? '<img class="pp-thumb" src="' + r.photo + '" alt="Push photo">' : '';
      var badge = r.billed ? '<span class="pp-badge pp-billed">billed</span>' : '<span class="pp-badge pp-unbilled">unbilled</span>';
      li.innerHTML =
        '<div class="pp-li-head"><span class="pp-li-title">' + esc(propName(r.propId)) + '</span>' +
        '<span>' + badge + ' <button type="button" class="pp-del" data-delrec="' + r.id + '" aria-label="Delete record">×</button></span></div>' +
        '<div class="pp-li-meta">' + esc(fmtTs(r.ts)) + ' · ' + esc(eventName(r.eventId)) + ' · ' + gps +
        (r.salt ? ' · Salt ' + esc(r.salt) + ' lbs' : '') +
        (r.notes ? '<br>Notes: ' + esc(r.notes) : '') + '</div>' + photo;
      ul.appendChild(li);
    });
  }

  function renderProps() {
    var p = load(K_PROPS);
    var recs = load(K_RECS);
    var ul = $('pp-proplist');
    ul.innerHTML = '';
    if (!p.length) {
      var li0 = document.createElement('li');
      li0.textContent = 'Add your first property above to start logging pushes.';
      ul.appendChild(li0);
      return;
    }
    p.forEach(function (x) {
      var count = recs.filter(function (r) { return r.propId === x.id; }).length;
      var li = document.createElement('li');
      li.innerHTML =
        '<div class="pp-li-head"><span class="pp-li-title">' + esc(x.name) + '</span>' +
        '<button type="button" class="pp-del" data-delprop="' + x.id + '" aria-label="Delete property">×</button></div>' +
        '<div class="pp-li-meta">' + esc(x.addr || 'No address') + ' · ' + money(x.rate) + ' per push · ' +
        count + ' pushes logged' + (x.contact ? ' · ' + esc(x.contact) : '') + '</div>';
      ul.appendChild(li);
    });
  }

  function renderEvents() {
    var ev = load(K_EVENTS);
    var recs = load(K_RECS);
    var ul = $('pp-eventlist');
    ul.innerHTML = '';
    ev.forEach(function (e) {
      var count = recs.filter(function (r) { return r.eventId === e.id; }).length;
      var badge = e.status === 'open' ? '<span class="pp-badge pp-open">open</span>' : '<span class="pp-badge pp-closed">closed</span>';
      var li = document.createElement('li');
      li.innerHTML =
        '<div class="pp-li-head"><span class="pp-li-title">' + esc(e.name) + ' ' + badge + '</span>' +
        '<span><button type="button" class="pp-btn pp-btn-ghost pp-toggleev" data-ev="' + e.id + '" style="padding:6px 12px;font-size:12px">' +
        (e.status === 'open' ? 'Close storm' : 'Reopen') + '</button> ' +
        '<button type="button" class="pp-del" data-delev="' + e.id + '" aria-label="Delete storm">×</button></span></div>' +
        '<div class="pp-li-meta">Started ' + esc(fmtTs(e.created)) + ' · ' + count + ' pushes logged</div>';
      ul.appendChild(li);
    });
    if (!ev.length) {
      var li0 = document.createElement('li');
      li0.textContent = 'No storm events yet.';
      ul.appendChild(li0);
    }
  }

  function renderBilling() {
    fillEventSelect($('pp-bill-event'), false);
    var sel = $('pp-bill-event');
    var keep = sel.getAttribute('data-sel');
    if (keep) sel.value = keep;
    var evId = sel.value;
    var recs = load(K_RECS).filter(function (r) { return r.eventId === evId; });
    var props = load(K_PROPS);
    var total = 0, billedTotal = 0, totalPushes = 0, unbilledPushes = 0;
    var ul = $('pp-billlist');
    ul.innerHTML = '';
    props.forEach(function (x) {
      var mine = recs.filter(function (r) { return r.propId === x.id; });
      if (!mine.length) return;
      var rate = parseFloat(x.rate) || 0;
      var amt = mine.length * rate;
      var b = mine.filter(function (r) { return r.billed; }).length;
      total += amt; totalPushes += mine.length;
      unbilledPushes += mine.length - b;
      billedTotal += b * rate;
      var li = document.createElement('li');
      li.innerHTML =
        '<div class="pp-li-head"><span class="pp-li-title">' + esc(x.name) + '</span><strong>' + money(amt) + '</strong></div>' +
        '<div class="pp-li-meta">' + mine.length + ' pushes × ' + money(rate) + ' · ' + b + ' billed, ' + (mine.length - b) + ' unbilled</div>';
      ul.appendChild(li);
    });
    if (!ul.children.length) {
      var li0 = document.createElement('li');
      li0.textContent = 'No pushes for this storm yet.';
      ul.appendChild(li0);
    }
    $('pp-billstats').innerHTML =
      '<div><strong>' + totalPushes + '</strong><span>pushes</span></div>' +
      '<div><strong>' + money(total) + '</strong><span>total</span></div>' +
      '<div><strong>' + money(total - billedTotal) + '</strong><span>unbilled</span></div>' +
      '<div class="pp-small">' + unbilledPushes + ' unbilled pushes</div>';
  }

  function csvCell(v) {
    v = String(v == null ? '' : v);
    return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v;
  }
  function downloadCSV() {
    var evId = $('pp-bill-event').value;
    var recs = load(K_RECS).filter(function (r) { return r.eventId === evId; });
    recs.sort(function (x, y) { return x.ts - y.ts; });
    var rows = [['storm', 'property', 'address', 'datetime', 'latitude', 'longitude', 'gps_accuracy_m', 'salt_lbs', 'notes', 'rate_per_push', 'amount', 'billed']];
    recs.forEach(function (r) {
      var p = load(K_PROPS);
      var addr = '', rate = 0;
      for (var i = 0; i < p.length; i++) if (p[i].id === r.propId) { addr = p[i].addr || ''; rate = parseFloat(p[i].rate) || 0; }
      rows.push([eventName(evId), propName(r.propId), addr, new Date(r.ts).toISOString(),
        r.lat != null ? r.lat : '', r.lng != null ? r.lng : '', r.acc != null ? r.acc : '',
        r.salt || '', r.notes || '', rate.toFixed(2), rate.toFixed(2), r.billed ? 'yes' : 'no']);
    });
    var csv = rows.map(function (row) { return row.map(csvCell).join(','); }).join('\r\n');
    var blob = new Blob([csv], { type: 'text/csv' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'pushproof-' + (eventName(evId).replace(/[^a-z0-9]+/gi, '-').toLowerCase()) + '.csv';
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { document.body.removeChild(a); URL.revokeObjectURL(a.href); }, 500);
  }

  function logPush() {
    var propSel = $('pp-prop');
    if (!propSel.value) {
      $('pp-gpsstatus').textContent = 'Add a property first — a push has to belong to someone.';
      return;
    }
    var btn = $('pp-logbtn');
    btn.disabled = true;
    $('pp-gpsstatus').textContent = 'Capturing GPS and photo…';
    var photoFile = $('pp-photo').files && $('pp-photo').files[0];
    var got = 0, gps = null, gpsErr = null, photo = null;
    function maybeDone() {
      got++;
      if (got < 2) return;
      var recs = load(K_RECS);
      var rec = {
        id: uid(), ts: Date.now(),
        eventId: $('pp-event').value, propId: $('pp-prop').value,
        lat: gps ? gps.lat : null, lng: gps ? gps.lng : null, acc: gps ? gps.acc : null,
        salt: $('pp-salt').value || '', notes: $('pp-notes').value || '',
        photo: photo, billed: false
      };
      recs.unshift(rec);
      save(K_RECS, recs);
      btn.disabled = false;
      $('pp-salt').value = '';
      $('pp-notes').value = '';
      $('pp-photo').value = '';
      var c = $('pp-confirm');
      c.hidden = false;
      c.textContent = 'Push logged at ' + fmtTs(rec.ts) + (gps ? ' — GPS ' + gps.lat.toFixed(5) + ', ' + gps.lng.toFixed(5) : ' — no GPS (saved anyway)');
      $('pp-gpsstatus').textContent = gpsErr ? 'GPS note: ' + gpsErr : 'GPS captured' + (gps && gps.acc ? ' (±' + gps.acc + 'm accuracy)' : '') + '.';
      refreshStats();
      renderRecords();
      renderEvents();
      renderBilling();
    }
    getGPS(function (pos, err) { gps = pos; gpsErr = err; maybeDone(); });
    readPhoto(photoFile, function (data) { photo = data; maybeDone(); });
  }

  function addProperty() {
    var name = $('pp-new-name').value.trim();
    if (!name) { $('pp-new-name').focus(); return; }
    var p = load(K_PROPS);
    p.push({ id: uid(), name: name, addr: $('pp-new-addr').value.trim(),
      rate: parseFloat($('pp-new-rate').value) || 0, contact: $('pp-new-contact').value.trim() });
    save(K_PROPS, p);
    $('pp-new-name').value = ''; $('pp-new-addr').value = '';
    $('pp-new-rate').value = ''; $('pp-new-contact').value = '';
    renderProps(); syncLogSelectors(); refreshStats();
  }

  function addEvent() {
    var name = $('pp-new-event').value.trim();
    var d = new Date();
    if (!name) name = 'Storm ' + d.toLocaleDateString();
    var ev = load(K_EVENTS);
    ev.forEach(function (e) { e.status = 'closed'; });
    ev.unshift({ id: uid(), name: name, status: 'open', created: Date.now() });
    save(K_EVENTS, ev);
    $('pp-new-event').value = '';
    renderEvents(); syncLogSelectors(); refreshStats();
  }

  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.classList && t.classList.contains('pp-tab')) {
      var tabs = root.querySelectorAll('.pp-tab');
      for (var i = 0; i < tabs.length; i++) tabs[i].classList.remove('pp-active');
      t.classList.add('pp-active');
      var panes = root.querySelectorAll('.pp-pane');
      for (var j = 0; j < panes.length; j++) panes[j].hidden = true;
      var pane = $('pp-pane-' + t.getAttribute('data-tab'));
      if (pane) pane.hidden = false;
      return;
    }
    if (t.id === 'pp-logbtn') { logPush(); return; }
    if (t.id === 'pp-addprop') { addProperty(); return; }
    if (t.id === 'pp-addevent') { addEvent(); return; }
    if (t.id === 'pp-csv') { downloadCSV(); return; }
    if (t.id === 'pp-markbilled') {
      var evId = $('pp-bill-event').value;
      var recs = load(K_RECS);
      var n = 0;
      recs.forEach(function (r) { if (r.eventId === evId && !r.billed) { r.billed = true; n++; } });
      save(K_RECS, recs);
      renderBilling(); renderRecords(); refreshStats();
      return;
    }
    if (t.classList && t.classList.contains('pp-toggleev')) {
      var ev = load(K_EVENTS);
      ev.forEach(function (x) {
        if (x.id === t.getAttribute('data-ev')) x.status = x.status === 'open' ? 'closed' : 'open';
      });
      save(K_EVENTS, ev);
      renderEvents(); syncLogSelectors(); refreshStats();
      return;
    }
    var delrec = t.getAttribute && t.getAttribute('data-delrec');
    if (delrec) {
      save(K_RECS, load(K_RECS).filter(function (r) { return r.id !== delrec; }));
      renderRecords(); renderBilling(); refreshStats();
      return;
    }
    var delprop = t.getAttribute && t.getAttribute('data-delprop');
    if (delprop) {
      save(K_PROPS, load(K_PROPS).filter(function (x) { return x.id !== delprop; }));
      renderProps(); syncLogSelectors(); refreshStats();
      return;
    }
    var delev = t.getAttribute && t.getAttribute('data-delev');
    if (delev) {
      save(K_EVENTS, load(K_EVENTS).filter(function (x) { return x.id !== delev; }));
      renderEvents(); syncLogSelectors(); refreshStats();
    }
  });

  root.addEventListener('change', function (e) {
    var t = e.target;
    if (t.id === 'pp-rec-event') { t.setAttribute('data-sel', t.value); renderRecords(); return; }
    if (t.id === 'pp-rec-prop') { t.setAttribute('data-sel', t.value); renderRecords(); return; }
    if (t.id === 'pp-bill-event') { t.setAttribute('data-sel', t.value); renderBilling(); }
  });

  (function init() {
    ensureEvent();
    syncLogSelectors();
    refreshStats();
    renderRecords();
    renderProps();
    renderEvents();
    renderBilling();
  })();
})();
